:root {
  --atlacolormarble-white: rgba(250, 250, 250, 1);
  --web-desktop-body-normal-font-family: "Libre Franklin", Helvetica;
  --web-desktop-body-normal-font-size: 14px;
  --web-desktop-body-normal-font-style: normal;
  --web-desktop-body-normal-font-weight: 500;
  --web-desktop-body-normal-letter-spacing: 0.2800000000000001px;
  --web-desktop-body-normal-line-height: 110%;
  --web-desktop-body-small-font-family: "Libre Franklin", Helvetica;
  --web-desktop-body-small-font-size: 12px;
  --web-desktop-body-small-font-style: normal;
  --web-desktop-body-small-font-weight: 600;
  --web-desktop-body-small-letter-spacing: 0.48px;
  --web-desktop-body-small-line-height: 120.00000762939453%;
  --web-desktop-h3-font-family: "ABC Synt Variable Unlicensed Trial", Helvetica;
  --web-desktop-h3-font-size: 64px;
  --web-desktop-h3-font-style: normal;
  --web-desktop-h3-font-weight: 400;
  --web-desktop-h3-letter-spacing: 0px;
  --web-desktop-h3-line-height: 110%;
}

